import React from "react";
import { Discrepancy } from "../App";

interface Props {
  discrepancies: Discrepancy[];
}

const DiscrepancyDashboard: React.FC<Props> = ({ discrepancies }) => {
  const group = (type: string) => discrepancies.filter(d => d.type === type);

  const price = group("Unit Price");
  const formulation = group("Formulation");
  const strength = group("Strength");
  const payer = group("Payer");

  const totalOvercharge = price.reduce((sum, d) => sum + ((d.invPrice ?? 0) - (d.refPrice ?? 0)), 0);

  return (
    <div style={{ marginTop: 20 }}>
      {/* Unit Price Table */}
      {price.length > 0 && (
        <>
          <h2>Unit Price Discrepancy Analysis</h2>
          <table>
            <thead>
              <tr>
                <th>Drug Name</th>
                <th>Recorded Price</th>
                <th>Expected Price</th>
                <th>Est. Overcharge</th>
                <th>% Discrepancy</th>
              </tr>
            </thead>
            <tbody>
              {price.map((d, i) => (
                <tr key={i}>
                  <td>{d.drugName}</td>
                  <td>${d.invPrice}</td>
                  <td>${d.refPrice}</td>
                  <td>${(d.invPrice! - d.refPrice!).toFixed(2)}</td>
                  <td>{d.percentOver}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <p><b>{price.length}</b> Price Discrepancies – <b>${totalOvercharge.toFixed(2)}</b> Total Overcharge</p>
        </>
      )}

      {/* Formulation */}
      {formulation.length > 0 && (
        <>
          <h2>Formulation Discrepancy Analysis</h2>
          <table>
            <thead>
              <tr>
                <th>Drug Name</th>
                <th>Recorded Formulation</th>
                <th>Expected Formulation</th>
              </tr>
            </thead>
            <tbody>
              {formulation.map((d, i) => (
                <tr key={i}>
                  <td>{d.drugName}</td>
                  <td>{d.invFormulation}</td>
                  <td>{d.refFormulation}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <p><b>{formulation.length}</b> Formulation Issues – Billing Error</p>
        </>
      )}

      {/* Strength */}
      {strength.length > 0 && (
        <>
          <h2>Strength Discrepancy Analysis</h2>
          <table>
            <thead>
              <tr>
                <th>Drug Name</th>
                <th>Recorded Strength</th>
                <th>Expected Strength</th>
              </tr>
            </thead>
            <tbody>
              {strength.map((d, i) => (
                <tr key={i}>
                  <td>{d.drugName}</td>
                  <td>{d.invStrength}</td>
                  <td>{d.refStrength}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <p><b>{strength.length}</b> Strength Errors – Safety Concern</p>
        </>
      )}

      {/* Payer */}
      {payer.length > 0 && (
        <>
          <h2>Payer Discrepancy Analysis</h2>
          <table>
            <thead>
              <tr>
                <th>Drug Name</th>
                <th>Recorded Payer</th>
                <th>Expected Payer</th>
              </tr>
            </thead>
            <tbody>
              {payer.map((d, i) => (
                <tr key={i}>
                  <td>{d.drugName}</td>
                  <td>{d.invPayer}</td>
                  <td>{d.refPayer}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <p><b>{payer.length}</b> Payer Mismatches – Claims Review Needed</p>
        </>
      )}

      {discrepancies.length === 0 && <p>No discrepancies found.</p>}

      {/* Summary */}
      {discrepancies.length > 0 && (
        <div style={{ marginTop: 20 }}>
          <h3>Summary</h3>
          <ul>
            <li>{price.length} Price Discrepancies – ${totalOvercharge.toFixed(2)} Total Overcharge</li>
            <li>{formulation.length} Formulation Issues – Billing Error</li>
            <li>{strength.length} Strength Errors – Safety Concern</li>
            <li>{payer.length} Payer Mismatches – Claims Review Needed</li>
            <li>{discrepancies.length} Total Issues – Requires Action</li>
          </ul>
        </div>
      )}
    </div>
  );
};

export default DiscrepancyDashboard;
